<script lang="ts">
 import {createEventDispatcher,onMount} from 'svelte';import type {Approval,ApprovalDecision} from './automations-client';import './automations.css';
 export let people:{id:string;name:string}[]=[];export let approval:Approval;export let actorId:string;export let busy=false;
 const dispatch=createEventDispatcher<{decision:{approval:Approval;decision:ApprovalDecision}}>();
 let confirm:ApprovalDecision|null=null,now=Date.now()/1000,seen='';
 $: if(seen!==approval.id+approval.status){seen=approval.id+approval.status;confirm=null;}
 $: canDecide=approval.canDecide&&approval.approverId===actorId&&approval.status==='PENDING'&&approval.expiresAt>now;
 const date=(n:number)=>new Date(n*1000).toLocaleString();
 onMount(()=>{const timer=setInterval(()=>now=Date.now()/1000,1000);return()=>clearInterval(timer);});
</script>
<section class="starli-automations approval-card" aria-label="Automation approval"><div class="sa-heading"><div><span class="sa-eyebrow">ACTION APPROVAL</span><h3>{approval.action==='internal_test_receipt'?'Review this internal approval test':approval.action==='slack_message_send'?'Review this exact Slack message':'Review this exact request'}</h3></div><span class="sa-badge">{approval.status==='PENDING'&&approval.expiresAt<=now?'Expired':approval.status.toLowerCase()}</span></div>
 <p class="sa-muted">{approval.action==='internal_test_receipt'?'This checks the approval flow and records an internal receipt. It does not authorize an external business action.':approval.action==='slack_message_send'?'Review the exact order, workspace, channel and message below. This decision authorizes only this message for this execution.':'This decision applies to one execution. Workflow activation does not authorize this action.'}</p>
 <dl class="sa-details">{#if approval.action==='refund_or_ticket'}<div><dt>Store</dt><dd>{approval.parameters.store}</dd></div><div><dt>Order</dt><dd>{approval.parameters.orderId}</dd></div><div><dt>Amount</dt><dd>{approval.parameters.amount} {approval.parameters.currency}</dd></div><div><dt>Payment provider</dt><dd>{approval.parameters.paymentProvider}</dd></div>{:else if approval.action==='slack_message_send'}<div><dt>Shopify store</dt><dd>{approval.parameters.shopDomain}</dd></div><div><dt>Order</dt><dd>{approval.parameters.orderName} · {approval.parameters.orderId}</dd></div><div><dt>Slack workspace</dt><dd>{approval.parameters.slackWorkspaceId}</dd></div><div><dt>Slack channel</dt><dd>{approval.parameters.slackChannelId}</dd></div><div class="message-body"><dt>Exact Slack message</dt><dd class="message-content">{approval.parameters.content}</dd></div>{:else}<div><dt>Internal test</dt><dd>{approval.parameters.label}</dd></div><div><dt>Authorized operation</dt><dd>Record an internal test receipt</dd></div>{/if}<div><dt>Assigned approver</dt><dd>{people.find(p=>p.id===approval.approverId)?.name||approval.approverId}{#if people.some(p=>p.id===approval.approverId)}<small class="sa-reference">{approval.approverId}</small>{/if}</dd></div><div><dt>Expires</dt><dd>{date(approval.expiresAt)}</dd></div><div><dt>Workflow</dt><dd>{approval.workflowId} · version {approval.workflowVersion}</dd></div><div><dt>Execution</dt><dd>{approval.executionId}</dd></div></dl>
 {#if canDecide}{#if confirm}<div class="sa-confirm"><strong>{confirm==='approve'?(approval.action==='slack_message_send'?'Send this exact Slack message?':'Approve this internal test?'):confirm==='refund'?'Authorize this exact refund?':confirm==='ticket'?'Create a support ticket for this request?':'Reject this request?'}</strong><p class="sa-muted">{confirm==='approve'?(approval.action==='slack_message_send'?'Authorize only the displayed message in the exact Slack workspace and channel for this order.':'Authorize only the internal receipt for this exact test execution. No external business action is authorized.'):confirm==='refund'?'Authorize only the store, order, amount and payment provider shown above.':confirm==='ticket'?'Authorize the permitted ticket branch for this exact execution.':'No action is authorized by this decision.'}</p><div class="sa-actions"><button disabled={busy} on:click={()=>confirm=null}>Back</button><button class="sa-primary" disabled={busy||!canDecide} on:click={()=>confirm&&dispatch('decision',{approval,decision:confirm})}>{busy?'Submitting…':'Confirm decision'}</button></div></div>{:else}<div class="sa-actions">{#if approval.action==='internal_test_receipt'}<button class="sa-primary" disabled={busy} on:click={()=>confirm='approve'}>Approve internal test</button>{:else if approval.action==='slack_message_send'}<button class="sa-primary" disabled={busy} on:click={()=>confirm='approve'}>Approve Slack message</button>{:else}<button class="sa-primary" disabled={busy} on:click={()=>confirm='refund'}>Approve refund</button><button disabled={busy} on:click={()=>confirm='ticket'}>Open ticket instead</button>{/if}<button class="sa-danger" disabled={busy} on:click={()=>confirm='reject'}>Reject</button></div>{/if}{:else if approval.status==='PENDING'&&approval.expiresAt>now}<p class="sa-muted">Waiting for the assigned approver. This same approval may also be decided through a connected notification.</p>{/if}
 {#if approval.decisionAt}<p class="sa-muted">Decided {date(approval.decisionAt)}{approval.decisionOrigin?' · '+approval.decisionOrigin:''}</p>{/if}<small class="sa-reference">Approval {approval.id}</small>
</section>

<style>.message-body{grid-column:1/-1}.message-content{white-space:pre-wrap;overflow-wrap:anywhere;border:1px solid #e6ebf4;border-radius:8px;background:#f6f8fc;padding:12px}</style>
